function salaryAddYearV6(){const rows=state.salaryModel.yearlyBases||[],last=rows.slice().sort((a,b)=>a.year-b.year).pop()||salaryYearConfigV6(parseJDate(todayJ()).y);rows.push({year:Number(last.year)+1,laborMonthlyBase:v6Num(last.laborMonthlyBase),employerInsuranceRate:v6Num(last.employerInsuranceRate),weeksFirstHalf:v6Num(last.weeksFirstHalf),weeksSecondHalf:v6Num(last.weeksSecondHalf)});renderView()}
