async function salarySaveSettingsV6(){const rows=[...document.querySelectorAll('[data-year-row]')].map(el=>({year:Math.floor(v6Num(el.querySelector('.v6-year').value)),laborMonthlyBase:v6Num(el.querySelector('.v6-base').value),employerInsuranceRate:v6Num(el.querySelector('.v6-ins').value)/100,weeksFirstHalf:v6Num(el.querySelector('.v6-w1').value),weeksSecondHalf:v6Num(el.querySelector('.v6-w2').value)})).filter(x=>x.year&&x.laborMonthlyBase);if(!rows.length)return toast('حداقل یک پایه سالانه ثبت کنید',true);state.salaryModel.yearlyBases=rows;state.salaryModel.standardWeeklyHours=v6Num($('salmv6_standard').value)||44;state.salaryModel.experienceStepPercent=v6Num($('salmv6_exp').value);state.salaryModel.roundingStep=v6Num($('salmv6_round').value)||500;SALARY_SCHEDULE_KEYS.forEach(k=>state.salaryModel.workHours[k]=v6Num($('salmv6_h_'+k).value));document.querySelectorAll('[data-v6-position]').forEach(e=>state.salaryModel.positionCoefficients[e.dataset.v6Position]=v6Num(e.value)||1);document.querySelectorAll('[data-v6-grade]').forEach(e=>state.salaryModel.gradeCoefficients[e.dataset.v6Grade]=v6Num(e.value)||1);const now=parseJDate(todayJ()),cfg=salaryYearConfigV6(now.y);state.salaryModel.laborMonthlyBase=cfg.laborMonthlyBase;state.salaryModel.weeksPerMonthFirstHalf=cfg.weeksFirstHalf;state.salaryModel.weeksPerMonthSecondHalf=cfg.weeksSecondHalf;await commit('ذخیره تنظیمات سالانه مدل حقوق')}
function moneyFieldUnitV6(field){const label=field.querySelector('label');if(!label)return'';const t=label.textContent;if(/ریال/.test(t))return'ریال';if(V6_MONEY_WORDS.test(t)&&!V6_NOT_MONEY.test(t))return'تومان';return''}
function enhanceNumericUIV6(){
  document.querySelectorAll('.data-table th,.data-table td').forEach(x=>x.style.textAlign='center');
  document.querySelectorAll('.field').forEach(field=>{const unit=moneyFieldUnitV6(field),input=field.querySelector('input');if(!unit||!input||input.hasAttribute('data-raw-number')||input.inputMode==='decimal'||input.dataset.v6Money==='1')return;field.dataset.moneyUnit=unit;input.dataset.v6Money='1';input.type='text';input.inputMode='numeric';input.value=input.value?v6Format(input.value):'';input.addEventListener('focus',()=>{input.value=v6Digits(input.value).replace(/[٬,\s]/g,'').replace(/[^0-9.\-]/g,'')});input.addEventListener('blur',()=>{input.value=v6Format(v6Num(input.value))});});
  document.querySelectorAll('.data-table').forEach(table=>{if(table.dataset.noCellUnit==='1')return;const heads=[...table.querySelectorAll('thead th')].map(x=>x.textContent.trim());table.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>{if(td.querySelector('input,select,button')||!/[۰-۹0-9]/.test(td.textContent))return;const h=heads[i]||'';let unit='';if(/ریال/.test(h))unit='ریال';else if(V6_MONEY_WORDS.test(h)&&!V6_NOT_MONEY.test(h))unit='تومان';if(unit&&!td.textContent.includes('تومان')&&!td.textContent.includes('ریال'))td.innerHTML=`${td.innerHTML}<span class="money-unit">${unit}</span>`}))});
  document.querySelectorAll('.kpi,.metric,.salary-result-card-v6').forEach(card=>{const label=card.querySelector('.label'),value=card.querySelector('.value');if(!label||!value||!/[۰-۹0-9]/.test(value.textContent))return;const t=label.textContent;let unit='';if(/ریال/.test(t))unit='ریال';else if(V6_MONEY_WORDS.test(t)&&!V6_NOT_MONEY.test(t))unit='تومان';if(unit&&!value.textContent.includes('تومان')&&!value.textContent.includes('ریال'))value.innerHTML+=`<span class="money-unit">${unit}</span>`});
}
